using Impersonate.Application.AiModels;using Impersonate.Domain.AiModels;using Microsoft.EntityFrameworkCore;
namespace Impersonate.Infrastructure.Persistence;
internal sealed class EfAiModelConfigurationRepository(ImpersonateDbContext db):IAiModelConfigurationRepository
{
 public async Task<IReadOnlyList<AiModelProfile>> ListModelsAsync(CancellationToken ct)=>await db.AiModelProfiles.OrderBy(x=>x.DisplayName).ToListAsync(ct);public Task<AiModelProfile?> GetModelAsync(Guid id,CancellationToken ct)=>db.AiModelProfiles.SingleOrDefaultAsync(x=>x.Id==id,ct);public Task<AiModelProfile?> FindModelAsync(string p,string i,CancellationToken ct)=>db.AiModelProfiles.SingleOrDefaultAsync(x=>x.Provider==p&&x.ModelIdentifier==i,ct);public Task AddModelAsync(AiModelProfile m,CancellationToken ct)=>db.AiModelProfiles.AddAsync(m,ct).AsTask();public async Task<IReadOnlyList<AgentModelAssignment>> ListAssignmentsAsync(Guid? project,CancellationToken ct)=>await db.AgentModelAssignments.Where(x=>x.ProjectId==project).OrderBy(x=>x.AgentRole).ToListAsync(ct);public Task<AgentModelAssignment?> GetAssignmentAsync(AgentRole role,Guid? project,CancellationToken ct)=>db.AgentModelAssignments.SingleOrDefaultAsync(x=>x.AgentRole==role&&x.ProjectId==project,ct);public Task AddAssignmentAsync(AgentModelAssignment a,CancellationToken ct)=>db.AgentModelAssignments.AddAsync(a,ct).AsTask();public void RemoveAssignment(AgentModelAssignment a)=>db.AgentModelAssignments.Remove(a);public Task SaveChangesAsync(CancellationToken ct)=>db.SaveChangesAsync(ct);
}
